import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump, CORE_SCHEMA, realMapTag } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    const data = {
      a: 1,
      b: 2,
      c: 3
    };
    const yaml = dump(data, {
      schema: CORE_SCHEMA.withTags(realMapTag)
    });
    const result = load(yaml, {
      schema: CORE_SCHEMA.withTags(realMapTag)
    });
    assert.deepEqual(result, data);
  });
});

